package com.anaiv.fluxogestao.repository;
import com.anaiv.fluxogestao.entity.OrdemPagamentoPorto; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import java.util.Collection; import java.util.List; import java.util.Optional;
